include "globals.mzn";

% Enums for categorical attributes
enum Nationality = {Englishman, Spaniard, Ukrainian, Norwegian, Japanese};
enum Color = {red, green, ivory, yellow, blue};
enum Pet = {dog, snails, fox, horse, zebra};
enum Drink = {coffee, tea, milk, orange_juice, water};
enum Cigarette = {Old_Gold, Kools, Chesterfields, Lucky_Strike, Parliaments};

% Decision variables: arrays indexed by house position 1..5
array[1..5] of var Nationality: nationality;
array[1..5] of var Color: color;
array[1..5] of var Pet: pet;
array[1..5] of var Drink: drink;
array[1..5] of var Cigarette: cigarette;

% Each attribute value appears exactly once across the five houses
constraint alldifferent(nationality);
constraint alldifferent(color);
constraint alldifferent(pet);
constraint alldifferent(drink);
constraint alldifferent(cigarette);

% The Englishman lives in the red house
constraint forall(h in 1..5)(
  (nationality[h] = Englishman) <-> (color[h] = red)
);

% The Spaniard owns the dog
constraint forall(h in 1..5)(
  (nationality[h] = Spaniard) <-> (pet[h] = dog)
);

% Coffee is drunk in the green house
constraint forall(h in 1..5)(
  (drink[h] = coffee) <-> (color[h] = green)
);

% The Ukrainian drinks tea
constraint forall(h in 1..5)(
  (nationality[h] = Ukrainian) <-> (drink[h] = tea)
);

% The green house is immediately to the right of the ivory house
constraint exists(h in 1..4)(
  (color[h] = ivory) /\ (color[h+1] = green)
);

% The Old Gold smoker owns snails
constraint forall(h in 1..5)(
  (cigarette[h] = Old_Gold) <-> (pet[h] = snails)
);

% Kools are smoked in the yellow house
constraint forall(h in 1..5)(
  (cigarette[h] = Kools) <-> (color[h] = yellow)
);

% Milk is drunk in the middle house (position 3)
constraint drink[3] = milk;

% The Norwegian lives in the first house (position 1)
constraint nationality[1] = Norwegian;

% The man who smokes Chesterfields lives next to the man with the fox
constraint exists(h in 1..5)(
  (cigarette[h] = Chesterfields) /\ 
  (exists(h2 in 1..5)((pet[h2] = fox) /\ (abs(h - h2) = 1)))
);

% Kools are smoked in the house next to the house where the horse is kept
constraint exists(h in 1..5)(
  (cigarette[h] = Kools) /\ 
  (exists(h2 in 1..5)((pet[h2] = horse) /\ (abs(h - h2) = 1)))
);

% The Lucky Strike smoker drinks orange juice
constraint forall(h in 1..5)(
  (cigarette[h] = Lucky_Strike) <-> (drink[h] = orange_juice)
);

% The Japanese smokes Parliaments
constraint forall(h in 1..5)(
  (nationality[h] = Japanese) <-> (cigarette[h] = Parliaments)
);

% The Norwegian lives next to the blue house
constraint exists(h in 1..5)(
  (nationality[h] = Norwegian) /\ 
  (exists(h2 in 1..5)((color[h2] = blue) /\ (abs(h - h2) = 1)))
);

include "globals.mzn";

enum Color = {Blue, Red, Green};
enum Animal = {Dog, Cat, Zebra};

array[1..3] of var Color: color;
array[1..3] of var Animal: animal;

% Constraint 1: Each house has exactly one color, and no two houses share the same color
constraint alldifferent(color);

% Constraint 2: Each house has exactly one animal, and no two houses have the same animal
constraint alldifferent(animal);

% Constraint 3: The Cat lives in the Red House
constraint exists(i in 1..3)(color[i] = Red /\ animal[i] = Cat);

% Constraint 4: The Red House is at position 2
constraint color[2] = Red;

% Constraint 5: The Blue House is directly to the left of the Red House
constraint exists(i in 1..3)(color[i] = Blue /\ exists(j in 1..3)(color[j] = Red /\ i = j - 1));

% Constraint 6: The Dog lives in the Blue House
constraint exists(i in 1..3)(color[i] = Blue /\ animal[i] = Dog);

include "globals.mzn";

enum Play = {Paper, Rock, Scissors};

var Play: you;
var Play: opponent;

constraint opponent = Rock;

constraint you = Paper;

enum CULPRIT = {Miss_Scarlett, Colonel_Mustard, Professor_Plum};
enum WEAPON = {Candlestick, Revolver, Rope};
enum ROOM = {Kitchen, Library, Conservatory};

var CULPRIT: culprit;
var WEAPON: weapon;
var ROOM: room;

constraint culprit != Colonel_Mustard;
constraint culprit != Miss_Scarlett;
constraint weapon != Revolver;
constraint weapon != Rope;
constraint room != Kitchen;
constraint room != Library;

include "globals.mzn";

var 0..9: S;
var 0..9: E;
var 0..9: N;
var 0..9: D;
var 0..9: M;
var 0..9: O;
var 0..9: R;
var 0..9: Y;

constraint alldifferent([S, E, N, D, M, O, R, Y]);

constraint S != 0;

constraint M != 0;

constraint 1000*S + 100*E + 10*N + D + 1000*M + 100*O + 10*R + E = 10000*M + 1000*O + 100*N + 10*E + Y;

include "globals.mzn";

% Entities
enum ENTITY = {Pedestrian, NorthCar, SouthCar, EastCar, WestCar};

% Arrival times (three distinct moments)
array[ENTITY] of var 1..3: arrivalTime;

% Crossing order (1 = first, 5 = last)
array[ENTITY] of var 1..5: crossingOrder;

% Constraint 11: Each crossing order position used exactly once
constraint alldifferent(crossingOrder);

% Constraints 6, 7, 8, 9, 10: Fixed arrival times
constraint arrivalTime[SouthCar] = 1;
constraint arrivalTime[Pedestrian] = 2;
constraint arrivalTime[EastCar] = 2;
constraint arrivalTime[NorthCar] = 3;
constraint arrivalTime[WestCar] = 3;

% Constraint 2: Pedestrian crosses before East car
constraint crossingOrder[Pedestrian] < crossingOrder[EastCar];

% Constraint 3: Earlier arrival time means crossing before later arrival time
constraint forall(e1, e2 in ENTITY where e1 != e2)(
  arrivalTime[e1] < arrivalTime[e2] -> crossingOrder[e1] < crossingOrder[e2]
);

% Constraint 4: Cars arriving simultaneously follow clockwise priority N, E, S, W
% Define clockwise priority for cars only
array[ENTITY] of int: carPriority = [5, 1, 3, 2, 4]; % Pedestrian=5(not used), North=1, South=3, East=2, West=4

constraint forall(e1, e2 in ENTITY where e1 != e2)(
  (e1 != Pedestrian /\ e2 != Pedestrian /\ arrivalTime[e1] = arrivalTime[e2] /\ carPriority[e1] < carPriority[e2]) 
  -> crossingOrder[e1] < crossingOrder[e2]
);

include "globals.mzn";

% Decision variables
var int: priya_score;
var int: sam_score;
var int: couple_tier;
var int: combined_income;
var int: combined_debt;
var int: dti_ratio;

enum LoanAmountStatus = {Within_limits, Exceeds_limits};
var LoanAmountStatus: loan_amount_status;

enum LoanOutcome = {Denied, Approved, Counter_Offer};
var LoanOutcome: outcome;

% Constraint 1: Couple's credit tier is minimum of individual scores
constraint couple_tier = min(priya_score, sam_score);

% Constraint 2: If credit tier below 600, loan is Denied
constraint couple_tier < 600 -> outcome = Denied;

% Constraint 3: DTI ratio calculation
constraint dti_ratio = (combined_debt * 100) div combined_income;

% Constraint 4: If DTI exceeds 43%, loan is Denied
constraint dti_ratio > 43 -> outcome = Denied;

% Constraint 5: If not denied and within limits, then Approved
constraint (outcome != Denied /\ loan_amount_status = Within_limits) -> outcome = Approved;

% Constraint 6: If not denied and exceeds limits, then Counter-Offer
constraint (outcome != Denied /\ loan_amount_status = Exceeds_limits) -> outcome = Counter_Offer;

% Constraint 7: Priya's credit score is 680
constraint priya_score = 680;

% Constraint 8: Sam's credit score is 750
constraint sam_score = 750;

% Constraint 9: Combined monthly income is $9,000
constraint combined_income = 9000;

% Constraint 10: Combined monthly debt payments are $3,200
constraint combined_debt = 3200;

% Constraint 11: Requested loan amount exceeds limits
constraint loan_amount_status = Exceeds_limits;

include "globals.mzn";

enum DRUG = {DrugA, DrugB, DrugC};

array[DRUG] of var {9, 11, 16}: drugTime;

constraint alldifferent(drugTime);

constraint drugTime[DrugB] >= drugTime[DrugA] + 4;

constraint abs(drugTime[DrugC] - 8) >= 2;

constraint abs(drugTime[DrugC] - 13) >= 2;

