constraint house[1] = Ana;

constraint forall(h in 1..3)(house[h] = Bo -> h != 2);

include "globals.mzn";

enum ITEM = {BagOfRice, HardcoverBookSet, CastIronSkillet, FirstAidKit, Toolbox};
enum STATUS = {packed, not_packed};

array[ITEM] of int: weight = [4, 3, 5, 2, 6];
array[ITEM] of int: value = [5, 4, 8, 6, 7];

array[ITEM] of var STATUS: inclusion;

constraint sum(i in ITEM)(if inclusion[i] == packed then weight[i] else 0 endif) <= 10;

constraint inclusion[FirstAidKit] == packed;

var int: total_value = sum(i in ITEM)(if inclusion[i] == packed then value[i] else 0 endif);

solve maximize total_value;

include "globals.mzn";

enum Color = {Red, Blue, Green, Yellow, White};

array[1..5] of var Color: color;

constraint alldifferent(color);

constraint color[1] = Red;

constraint color[4] = White;

constraint exists(i in 1..5)(color[i] = Blue) /\
           exists(j in 1..5)(color[j] = Green /\ 
           exists(i in 1..5)(color[i] = Blue /\ j > i));

include "globals.mzn";

% Enums for categorical values
enum ITEM = {ice_cream, beans, flour, bananas};
enum TEMP = {below_freezing, above_freezing};

% Compartments are numbered 1..4
set of int: COMPARTMENT = 1..4;

% Decision variables
array[COMPARTMENT] of var ITEM: item_in_compartment;

% Fixed temperature conditions for each compartment
array[COMPARTMENT] of TEMP: temp_condition = [below_freezing, above_freezing, above_freezing, above_freezing];

% Constraint: Each compartment holds exactly one grocery item
% Constraint: Each grocery item is in exactly one compartment
constraint alldifferent(item_in_compartment);

% Constraint: Ice cream must not melt
% Ice cream melts if in a compartment with temperature "above freezing"
% Therefore, ice cream must be in a compartment with temperature "below freezing"
constraint forall(c in COMPARTMENT)(
  item_in_compartment[c] = ice_cream -> temp_condition[c] = below_freezing
);

solve satisfy;

include "globals.mzn";

enum ANIMAL = {wolf, rabbit, goat, parrot, tortoise};

array[1..5] of var ANIMAL: pen;

constraint pen[1] = tortoise;
constraint pen[2] = parrot;
constraint pen[3] = goat;

constraint exists(i in 1..5)(pen[i] = rabbit) /\ 
           exists(j in 1..5)(pen[j] = wolf /\ 
           exists(k in 1..5)(pen[k] = rabbit /\ k < j));

constraint alldifferent(pen);
